      mean: { name: "mean", detail: "\u0645\u0637\u0644\u0648\u0628. \u0627\u0644\u0648\u0633\u0637 \u0627\u0644\u062D\u0633\u0627\u0628\u064A \u0644\u0644\u062A\u0648\u0632\u064A\u0639" },
      standardDev: { name: "standard_dev", detail: "\u0645\u0637\u0644\u0648\u0628. \u0627\u0644\u0627\u0646\u062D\u0631\u0627\u0641 \u0627\u0644\u0645\u0639\u064A\u0627\u0631\u064A \u0644\u0644\u062A\u0648\u0632\u064A\u0639" },
      cumulative: { name: "cumulative", detail: "\u0645\u0637\u0644\u0648\u0628. \u0627\u0644\u0642\u064A\u0645\u0629 \u0627\u0644\u0645\u0646\u0637\u0642\u064A\u0629 \u0627\u0644\u062A\u064A \u062A\u062D\u062F\u062F \u0634\u0643\u0644 \u0627\u0644\u062F\u0627\u0644\u0629. \u0625\u0630\u0627 \u0643\u0627\u0646\u062A \u0627\u0644\u0642\u064A\u0645\u0629 \u0627\u0644\u062A\u0631\u0627\u0643\u0645\u064A\u0629 TRUE\u060C \u0641\u062A\u0631\u062C\u0639 \u0627\u0644\u062F\u0627\u0644\u0629 NORMDIST \u062F\u0627\u0644\u0629 \u0627\u0644\u062A\u0648\u0632\u064A\u0639 \u0627\u0644\u062A\u0631\u0627\u0643\u0645\u064A\u061B \u0625\u0630\u0627 \u0643\u0627\u0646\u062A \u0627\u0644\u0642\u064A\u0645\u0629 \u0627\u0644\u062A\u0631\u0627\u0643\u0645\u064A\u0629 FALSE\u060C \u0641\u0625\u0646\u0647\u0627 \u062A\u0631\u062C\u0639 \u062F\u0627\u0644\u0629 \u0627\u0644\u0627\u062D\u062A\u0645\u0627\u0644\u0627\u062A \u0627\u0644\u062C\u0645\u0627\u0639\u064A\u0629." }
