      x: { name: "x", detail: "\u0645\u0637\u0644\u0648\u0628\u0629. \u0627\u0644\u0642\u064A\u0645\u0629 \u0627\u0644\u062A\u064A \u064A\u062C\u0628 \u0627\u062E\u062A\u0628\u0627\u0631\u0647\u0627." },
      sigma: { name: "sigma", detail: "\u0627\u0644\u0627\u062E\u062A\u064A\u0627\u0631\u064A. \u0627\u0644\u0627\u0646\u062D\u0631\u0627\u0641 \u0627\u0644\u0645\u0639\u064A\u0627\u0631\u064A \u0644\u0644\u0645\u062D\u062A\u0648\u0649 (\u0645\u0639\u0631\u0648\u0641). \u0641\u064A \u062D\u0627\u0644\u0629 \u062D\u0630\u0641\u0647\u0627\u060C \u064A\u062A\u0645 \u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0627\u0644\u0627\u0646\u062D\u0631\u0627\u0641 \u0627\u0644\u0645\u0639\u064A\u0627\u0631\u064A \u0644\u0644\u0639\u064A\u0646\u0629." }
