    functionParameter: {
      dateText: { name: "date_text", detail: '\u0645\u0637\u0644\u0648\u0628. \u0648\u0647\u064A \u0627\u0644\u0646\u0635 \u0627\u0644\u0630\u064A \u064A\u0645\u062B\u0644 \u062A\u0627\u0631\u064A\u062E\u0627\u064B \u0628\u062A\u0646\u0633\u064A\u0642 \u062A\u0627\u0631\u064A\u062E \u0644\u0640 Excel \u0623\u0648 \u0645\u0631\u062C\u0639\u0627\u064B \u0644\u0644\u062E\u0644\u064A\u0629 \u0627\u0644\u062A\u064A \u062A\u062D\u062A\u0648\u064A \u0639\u0644\u0649 \u0646\u0635 \u064A\u0645\u062B\u0644 \u062A\u0627\u0631\u064A\u062E\u0627\u064B \u0628\u062A\u0646\u0633\u064A\u0642 \u062A\u0627\u0631\u064A\u062E \u0644\u0640 Excel. \u0639\u0644\u0649 \u0633\u0628\u064A\u0644 \u0627\u0644\u0645\u062B\u0627\u0644\u060C \u064A\u0639\u062F \u0627\u0644\u062A\u0627\u0631\u064A\u062E "30/1/2008" \u0623\u0648 "30 - \u064A\u0646\u0627\u064A\u0631 - 2008" \u0639\u0628\u0627\u0631\u0629 \u0639\u0646 \u0633\u0644\u0633\u0644\u0629 \u0646\u0635\u064A\u0629 \u0645\u0648\u062C\u0648\u062F\u0629 \u062F\u0627\u062E\u0644 \u0639\u0644\u0627\u0645\u062A\u064A \u0627\u0642\u062A\u0628\u0627\u0633 \u0648\u062A\u0645\u062B\u0644 \u062A\u0627\u0631\u064A\u062E\u0627\u064B. \u0628\u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0646\u0638\u0627\u0645 \u0627\u0644\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0627\u0641\u062A\u0631\u0627\u0636\u064A \u0641\u064A Microsoft Excel for Windows\u060C \u064A\u062C\u0628 \u0623\u0646 \u062A\u0645\u062B\u0644 \u0627\u0644\u0648\u0633\u064A\u0637\u0629 date_text \u062A\u0627\u0631\u064A\u062E\u0627 \u0628\u064A\u0646 1 \u064A\u0646\u0627\u064A\u0631 1900 \u064831 \u062F\u064A\u0633\u0645\u0628\u0631 9999. \u062A\u0631\u062C\u0639 \u0627\u0644\u062F\u0627\u0644\u0629 DATEVALUE #VALUE! \u0642\u064A\u0645\u0629 \u0627\u0644\u062E\u0637\u0623 \u0625\u0630\u0627 \u0643\u0627\u0646\u062A \u0642\u064A\u0645\u0629 \u0627\u0644\u0648\u0633\u064A\u0637\u0629 date_text \u062A\u0642\u0639 \u062E\u0627\u0631\u062C \u0647\u0630\u0627 \u0627\u0644\u0646\u0637\u0627\u0642. \u0625\u0630\u0627 \u062A\u0645 \u062D\u0630\u0641 \u062C\u0632\u0621 \u0627\u0644\u0633\u0646\u0629 \u0645\u0646 \u0627\u0644\u0648\u0633\u064A\u0637\u0629 date_text \u060C \u062A\u0633\u062A\u062E\u062F\u0645 \u0627\u0644\u062F\u0627\u0644\u0629 DATEVALUE \u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u062D\u0627\u0644\u064A\u0629 \u0645\u0646 \u0627\u0644\u0633\u0627\u0639\u0629 \u0627\u0644\u0645\u0636\u0645\u0646\u0629 \u0641\u064A \u0627\u0644\u0643\u0645\u0628\u064A\u0648\u062A\u0631. \u064A\u062A\u0645 \u062A\u062C\u0627\u0647\u0644 \u0645\u0639\u0644\u0648\u0645\u0627\u062A \u0627\u0644\u0648\u0642\u062A \u0641\u064A \u0627\u0644\u0648\u0633\u064A\u0637\u0629 date_text .' }
    }
