    functionParameter: {
      startDate: { name: "start_date", detail: "\u062A\u0627\u0631\u064A\u062E \u064A\u0645\u062B\u0644 \u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0628\u062F\u0621." },
      endDate: { name: "end_date", detail: "\u062A\u0627\u0631\u064A\u062E \u064A\u0645\u062B\u0644 \u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0627\u0646\u062A\u0647\u0627\u0621." },
      weekend: { name: "weekend", detail: "\u0631\u0642\u0645 \u0623\u0648 \u0633\u0644\u0633\u0644\u0629 \u0646\u0635\u064A\u0629 \u062A\u062D\u062F\u062F \u0623\u064A\u0627\u0645 \u0639\u0637\u0644\u0629 \u0646\u0647\u0627\u064A\u0629 \u0627\u0644\u0623\u0633\u0628\u0648\u0639." },
      holidays: { name: "holidays", detail: "\u0646\u0637\u0627\u0642 \u0627\u062E\u062A\u064A\u0627\u0631\u064A \u064A\u062A\u0636\u0645\u0646 \u062A\u0627\u0631\u064A\u062E\u0627\u064B \u0648\u0627\u062D\u062F\u0627\u064B \u0623\u0648 \u0623\u0643\u062B\u0631 \u0644\u0627\u0633\u062A\u0628\u0639\u0627\u062F\u0647 \u0645\u0646 \u062A\u0642\u0648\u064A\u0645 \u0627\u0644\u0639\u0645\u0644\u060C \u0645\u062B\u0644 \u0627\u0644\u0639\u0637\u0644\u0627\u062A \u0627\u0644\u0631\u0633\u0645\u064A\u0629 \u0623\u0648 \u0627\u0644\u0639\u0637\u0644\u0627\u062A \u0627\u0644\u0645\u062A\u062D\u0631\u0643\u0629." }
    }
