      endDate: { name: "end_date", detail: "\u062A\u0627\u0631\u064A\u062E \u064A\u0645\u062B\u0644 \u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0627\u0646\u062A\u0647\u0627\u0621." },
      basis: { name: "basis", detail: "\u0646\u0648\u0639 \u0623\u0633\u0627\u0633 \u0627\u062D\u062A\u0633\u0627\u0628 \u0627\u0644\u0623\u064A\u0627\u0645 \u0627\u0644\u0645\u0631\u0627\u062F \u0627\u0633\u062A\u062E\u062F\u0627\u0645\u0647." }
