    functionParameter: {
      issue: { name: "issue", detail: "\u0645\u0637\u0644\u0648\u0628. \u0648\u0647\u064A \u062A\u0627\u0631\u064A\u062E \u0625\u0635\u062F\u0627\u0631 \u0627\u0644\u0648\u0631\u0642\u0629 \u0627\u0644\u0645\u0627\u0644\u064A\u0629." },
      settlement: { name: "settlement", detail: "\u0645\u0637\u0644\u0648\u0628. \u0648\u0647\u064A \u062A\u0627\u0631\u064A\u062E \u0627\u0633\u062A\u062D\u0642\u0627\u0642 \u0627\u0644\u0648\u0631\u0642\u0629 \u0627\u0644\u0645\u0627\u0644\u064A\u0629." },
      rate: { name: "rate", detail: "\u0645\u0637\u0644\u0648\u0628. \u0648\u0647\u064A \u0627\u0644\u0633\u0639\u0631 \u0627\u0644\u0633\u0646\u0648\u064A \u0644\u0641\u0627\u0626\u062F\u0629 \u0627\u0644\u0642\u0633\u064A\u0645\u0629 \u0627\u0644\u062E\u0627\u0635\u0629 \u0628\u0627\u0644\u0648\u0631\u0642\u0629 \u0627\u0644\u0645\u0627\u0644\u064A\u0629." },
      par: { name: "par", detail: "\u0645\u0637\u0644\u0648\u0628. \u0648\u0647\u064A \u0642\u064A\u0645\u0629 \u0633\u0639\u0631 \u0627\u0644\u062A\u062F\u0627\u0648\u0644 \u0644\u0644\u0648\u0631\u0642\u0629 \u0627\u0644\u0645\u0627\u0644\u064A\u0629. \u0625\u0630\u0627 \u062A\u0645 \u0625\u0647\u0645\u0627\u0644 \u0633\u0639\u0631 \u0627\u0644\u062A\u062F\u0627\u0648\u0644\u060C \u0641\u0633\u062A\u0633\u062A\u062E\u062F\u0645 \u0627\u0644\u062F\u0627\u0644\u0629 ACCRINTM \u0627\u0644\u0642\u064A\u0645\u0629 1000 \u0631.\u0633.." },
      basis: { name: "basis", detail: "\u0627\u0644\u0627\u062E\u062A\u064A\u0627\u0631\u064A. \u0648\u0647\u064A \u0646\u0648\u0639 \u0623\u0633\u0627\u0633 \u062D\u0633\u0627\u0628 \u0639\u062F\u062F \u0627\u0644\u0623\u064A\u0627\u0645 \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0627\u0633\u062A\u062E\u062F\u0627\u0645\u0647." }
    }
