      salvage: { name: "salvage", detail: "\u0645\u0637\u0644\u0648\u0628. \u0648\u0647\u064A \u0627\u0644\u0642\u064A\u0645\u0629 \u0627\u0644\u0628\u0627\u0642\u064A\u0629 \u0641\u064A \u0646\u0647\u0627\u064A\u0629 \u0641\u062A\u0631\u0629 \u0639\u0645\u0631 \u0627\u0644\u0623\u0635\u0644." },
