    abstract: "\u062A\u064F\u0631\u062C\u0639 \u0647\u0630\u0647 \u0627\u0644\u062F\u0627\u0644\u0629 \u0625\u0647\u0644\u0627\u0643 \u0623\u0635\u0648\u0644 \u0644\u0641\u062A\u0631\u0629 \u0645\u0639\u064A\u0646\u0629 \u0628\u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0623\u0633\u0644\u0648\u0628 \u0627\u0644\u0631\u0635\u064A\u062F \u0627\u0644\u0645\u062A\u0646\u0627\u0642\u0635 \u0627\u0644\u062B\u0627\u0628\u062A.",
