      salvage: { name: "salvage", detail: "\u0645\u0637\u0644\u0648\u0628. \u0627\u0644\u0642\u064A\u0645\u0629 \u0639\u0646\u062F \u0646\u0647\u0627\u064A\u0629 \u0627\u0644\u0625\u0647\u0644\u0627\u0643 (\u0648\u062A\u0633\u0645\u0649 \u0641\u064A \u0628\u0639\u0636 \u0627\u0644\u0623\u062D\u064A\u0627\u0646 \u0627\u0644\u0642\u064A\u0645\u0629 \u0627\u0644\u0628\u0627\u0642\u064A\u0629 \u0644\u0644\u0623\u0635\u0648\u0644). \u0642\u062F \u062A\u0643\u0648\u0646 \u0647\u0630\u0647 \u0627\u0644\u0642\u064A\u0645\u0629 0." },
      life: { name: "life", detail: "\u0645\u0637\u0644\u0648\u0628. \u0639\u062F\u062F \u0627\u0644\u0641\u062A\u0631\u0627\u062A \u0627\u0644\u062A\u064A \u064A\u062A\u0645 \u0641\u064A\u0647\u0627 \u0625\u0647\u0644\u0627\u0643 \u0627\u0644\u0623\u0635\u0644 (\u062A\u0633\u0645\u0649 \u0623\u062D\u064A\u0627\u0646\u0627\u064B \u0627\u0644\u0639\u0645\u0631 \u0627\u0644\u0625\u0646\u062A\u0627\u062C\u064A \u0644\u0644\u0623\u0635\u0644)." },
      period: { name: "period", detail: "\u0645\u0637\u0644\u0648\u0628. \u0627\u0644\u0641\u062A\u0631\u0629 \u0627\u0644\u062A\u064A \u062A\u0631\u064A\u062F \u062D\u0633\u0627\u0628 \u0627\u0644\u0625\u0647\u0644\u0627\u0643 \u0641\u064A\u0647\u0627. \u064A\u062C\u0628 \u0623\u0646 \u062A\u0633\u062A\u062E\u062F\u0645 \u0627\u0644\u0648\u0633\u064A\u0637\u0629 Period \u0627\u0644\u0648\u062D\u062F\u0627\u062A \u0646\u0641\u0633\u0647\u0627 \u0627\u0644\u062A\u064A \u062A\u0633\u062A\u062E\u062F\u0645\u0647\u0627 \u0627\u0644\u0648\u0633\u064A\u0637\u0629 life." },
      factor: { name: "factor", detail: "\u0627\u0644\u0627\u062E\u062A\u064A\u0627\u0631\u064A. \u0627\u0644\u0645\u0639\u062F\u0644 \u0627\u0644\u0630\u064A \u062A\u062A\u0631\u0627\u062C\u0639 \u0639\u0646\u062F\u0647 \u0627\u0644\u0645\u064A\u0632\u0627\u0646\u064A\u0629. \u0625\u0630\u0627 \u062A\u0645 \u062D\u0630\u0641 \u0627\u0644\u0648\u0633\u064A\u0637\u0629 factor\u060C \u0641\u0633\u064A\u0641\u062A\u0631\u0636 \u0623\u0646\u0647\u0627 2 (\u0623\u0633\u0644\u0648\u0628 \u0627\u0644\u0627\u0633\u062A\u0647\u0644\u0627\u0643 \u0627\u0644\u0645\u062A\u0646\u0627\u0642\u0635 \u0627\u0644\u0645\u0632\u062F\u0648\u062C)." }
