      schedule: { name: "schedule", detail: "\u0645\u0637\u0644\u0648\u0628. \u0635\u0641\u064A\u0641 \u0645\u0639\u062F\u0644\u0627\u062A \u0627\u0644\u0641\u0627\u0626\u062F\u0629 \u0627\u0644\u062A\u064A \u062A\u0631\u064A\u062F \u062A\u0637\u0628\u064A\u0642\u0647\u0627." }
