    functionParameter: {
      rate: { name: "rate", detail: "\u0645\u0637\u0644\u0648\u0628\u0629. \u0645\u0639\u062F\u0644 \u0627\u0644\u0641\u0627\u0626\u062F\u0629 \u0644\u0644\u0627\u0633\u062A\u062B\u0645\u0627\u0631." },
      per: { name: "per", detail: "\u0645\u0637\u0644\u0648\u0628\u0629. \u0627\u0644\u0641\u062A\u0631\u0629 \u0627\u0644\u062A\u064A \u062A\u0631\u064A\u062F \u0627\u0644\u0639\u062B\u0648\u0631 \u0639\u0644\u0649 \u0627\u0644\u0641\u0627\u0626\u062F\u0629 \u0644\u0647\u0627\u060C \u0648\u064A\u062C\u0628 \u0623\u0646 \u062A\u0643\u0648\u0646 \u0628\u064A\u0646 1 \u0648Nper." },
      nper: { name: "nper", detail: "\u0645\u0637\u0644\u0648\u0628\u0629. \u0627\u0644\u0639\u062F\u062F \u0627\u0644\u0625\u062C\u0645\u0627\u0644\u064A \u0644\u0641\u062A\u0631\u0627\u062A \u0627\u0644\u062F\u0641\u0639 \u0644\u0644\u0627\u0633\u062A\u062B\u0645\u0627\u0631." },
      pv: { name: "pv", detail: "\u0645\u0637\u0644\u0648\u0628\u0629. \u0627\u0644\u0642\u064A\u0645\u0629 \u0627\u0644\u062D\u0627\u0644\u064A\u0629 \u0644\u0644\u0627\u0633\u062A\u062B\u0645\u0627\u0631. \u0628\u0627\u0644\u0646\u0633\u0628\u0629 \u0644\u0644\u0642\u0631\u0636\u060C Pv \u0647\u0648 \u0645\u0628\u0644\u063A \u0627\u0644\u0642\u0631\u0636." }
    }
