      npery: { name: "npery", detail: "\u0645\u0637\u0644\u0648\u0628. \u0639\u062F\u062F \u0627\u0644\u0641\u062A\u0631\u0627\u062A \u0627\u0644\u0645\u062A\u0631\u0627\u0643\u0628\u0629 \u0643\u0644 \u0633\u0646\u0629." }
