      nper: { name: "nper", detail: "\u0645\u0637\u0644\u0648\u0628. \u0627\u0644\u0639\u062F\u062F \u0627\u0644\u0625\u062C\u0645\u0627\u0644\u064A \u0644\u062F\u0641\u0639\u0627\u062A \u062A\u0633\u062F\u064A\u062F \u0627\u0644\u0642\u0631\u0636." },
      pv: { name: "pv", detail: "\u0645\u0637\u0644\u0648\u0628. \u0627\u0644\u0642\u064A\u0645\u0629 \u0627\u0644\u062D\u0627\u0644\u064A\u0629\u060C \u0623\u0648 \u0627\u0644\u0645\u0628\u0644\u063A \u0627\u0644\u0625\u062C\u0645\u0627\u0644\u064A \u0627\u0644\u0630\u064A \u062A\u0633\u0627\u0648\u064A\u0647 \u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062F\u0641\u0639\u0627\u062A \u0627\u0644\u0645\u0633\u062A\u0642\u0628\u0644\u064A\u0629 \u0627\u0644\u0622\u0646\u061B \u0648\u062A\u064F\u0639\u0631\u0641 \u0623\u064A\u0636\u0627\u064B \u0628\u0631\u0623\u0633 \u0627\u0644\u0645\u0627\u0644." },
      fv: { name: "fv", detail: "\u0627\u0644\u0627\u062E\u062A\u064A\u0627\u0631\u064A. \u0627\u0644\u0642\u064A\u0645\u0629 \u0627\u0644\u0645\u0633\u062A\u0642\u0628\u0644\u064A\u0629 \u0623\u0648 \u0627\u0644\u0645\u064A\u0632\u0627\u0646\u064A\u0629 \u0627\u0644\u0646\u0642\u062F\u064A\u0629 \u0627\u0644\u062A\u064A \u062A\u0631\u064A\u062F \u062A\u062D\u0642\u064A\u0642\u0647\u0627 \u0628\u0639\u062F \u0625\u062A\u0645\u0627\u0645 \u0627\u0644\u062F\u0641\u0639\u0629 \u0627\u0644\u0623\u062E\u064A\u0631\u0629. \u0625\u0630\u0627 \u062A\u0645 \u062D\u0630\u0641 fv\u060C \u0641\u0633\u064A\u0641\u062A\u0631\u0636 \u0623\u0646\u0647\u0627 0 (\u0635\u0641\u0631)\u060C \u0623\u064A \u0623\u0646 \u0627\u0644\u0642\u064A\u0645\u0629 \u0627\u0644\u0645\u0633\u062A\u0642\u0628\u0644\u064A\u0629 \u0644\u0642\u0631\u0636 \u0645\u062B\u0644\u0627\u064B \u062A\u0633\u0627\u0648\u064A \u0635\u0641\u0631." },
