      maturity: { name: "maturity", detail: "\u0645\u0637\u0644\u0648\u0628. \u0648\u0647\u064A \u062A\u0627\u0631\u064A\u062E \u0627\u0633\u062A\u062D\u0642\u0627\u0642 \u0627\u0644\u0648\u0631\u0642\u0629 \u0627\u0644\u0645\u0627\u0644\u064A\u0629. \u064A\u0645\u062B\u0644 \u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0627\u0633\u062A\u062D\u0642\u0627\u0642 \u062A\u0627\u0631\u064A\u062E \u0627\u0646\u062A\u0647\u0627\u0621 \u0635\u0644\u0627\u062D\u064A\u0629 \u0627\u0644\u0648\u0631\u0642\u0629 \u0627\u0644\u0645\u0627\u0644\u064A\u0629." },
      rate: { name: "rate", detail: "\u0645\u0637\u0644\u0648\u0628. \u0648\u0647\u064A \u0627\u0644\u0633\u0639\u0631 \u0627\u0644\u0633\u0646\u0648\u064A \u0644\u0641\u0627\u0626\u062F\u0629 \u0627\u0644\u0642\u0633\u064A\u0645\u0629 \u0627\u0644\u062E\u0627\u0635\u0629 \u0628\u0627\u0644\u0648\u0631\u0642\u0629 \u0627\u0644\u0645\u0627\u0644\u064A\u0629." },
      yld: { name: "yld", detail: "\u0645\u0637\u0644\u0648\u0628. \u0627\u0644\u0639\u0627\u0626\u062F \u0627\u0644\u0633\u0646\u0648\u064A \u0644\u0644\u0648\u0631\u0642\u0629 \u0627\u0644\u0645\u0627\u0644\u064A\u0629." },
      redemption: { name: "redemption", detail: "\u0645\u0637\u0644\u0648\u0628. \u0642\u064A\u0645\u0629 \u0627\u0633\u062A\u0631\u062F\u0627\u062F \u0627\u0644\u0648\u0631\u0642\u0629 \u0627\u0644\u0645\u0627\u0644\u064A\u0629 \u0644\u0643\u0644 \u0642\u064A\u0645\u0629 \u0627\u0633\u0645\u064A\u0629 \u0642\u062F\u0631\u0647\u0627 100 \u0631.\u0633." },
      frequency: { name: "frequency", detail: "\u0645\u0637\u0644\u0648\u0628. \u0648\u0647\u064A \u0639\u062F\u062F \u0645\u062F\u0641\u0648\u0639\u0627\u062A \u0627\u0644\u0642\u0633\u064A\u0645\u0629 \u0641\u064A \u0627\u0644\u0633\u0646\u0629. \u0628\u0627\u0644\u0646\u0633\u0628\u0629 \u0625\u0644\u0649 \u0627\u0644\u0645\u062F\u0641\u0648\u0639\u0627\u062A \u0627\u0644\u0633\u0646\u0648\u064A\u0629\u060C frequency = 1\u061B \u0648\u0627\u0644\u0645\u062F\u0641\u0648\u0639\u0627\u062A \u0646\u0635\u0641 \u0627\u0644\u0633\u0646\u0648\u064A\u0629\u060C frequency = 2\u061B \u0648\u0627\u0644\u0645\u062F\u0641\u0648\u0639\u0627\u062A \u0631\u0628\u0639 \u0627\u0644\u0633\u0646\u0648\u064A\u0629\u060C frequency = 4." },
      basis: { name: "basis", detail: "\u0627\u0644\u0627\u062E\u062A\u064A\u0627\u0631\u064A. \u0648\u0647\u064A \u0646\u0648\u0639 \u0623\u0633\u0627\u0633 \u062D\u0633\u0627\u0628 \u0639\u062F\u062F \u0627\u0644\u0623\u064A\u0627\u0645 \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0627\u0633\u062A\u062E\u062F\u0627\u0645\u0647." }
