    functionParameter: {
      nper: { name: "nper", detail: "\u0645\u0637\u0644\u0648\u0628. \u0627\u0644\u0639\u062F\u062F \u0627\u0644\u0625\u062C\u0645\u0627\u0644\u064A \u0644\u0641\u062A\u0631\u0627\u062A \u0627\u0644\u062F\u0641\u0639\u0627\u062A \u0641\u064A \u0627\u0644\u0645\u0631\u062A\u0628 \u0627\u0644\u062F\u0648\u0631\u064A." },
      pmt: { name: "pmt", detail: "\u0645\u0637\u0644\u0648\u0628. \u0627\u0644\u062F\u0641\u0639\u0629 \u0627\u0644\u062A\u064A \u062A\u0645 \u062A\u0633\u062F\u064A\u062F\u0647\u0627 \u0641\u064A \u0643\u0644 \u0641\u062A\u0631\u0629 \u0648\u0644\u0627 \u064A\u0645\u0643\u0646 \u0623\u0646 \u062A\u062A\u063A\u064A\u0631 \u0639\u0644\u0649 \u0645\u062F\u0649 \u0639\u0645\u0631 \u0627\u0644\u0645\u0631\u062A\u0628 \u0627\u0644\u062F\u0648\u0631\u064A. \u062A\u062D\u062A\u0648\u064A \u0648\u0633\u064A\u0637\u0629 \u0627\u0644\u062F\u0641\u0639\u0629 \u0639\u0627\u062F\u0629\u064B \u0639\u0644\u0649 \u0631\u0623\u0633 \u0645\u0627\u0644 \u0648\u0641\u0627\u0626\u062F\u0629 \u0648\u0644\u0643\u0646 \u0628\u062F\u0648\u0646 \u0631\u0633\u0648\u0645 \u0623\u0648 \u0636\u0631\u0627\u0626\u0628 \u0623\u062E\u0631\u0649. \u0625\u0630\u0627 \u062A\u0645 \u062D\u0630\u0641 \u0627\u0644\u0648\u0633\u064A\u0637\u0629 pmt\u060C \u0641\u064A\u062C\u0628 \u062A\u0636\u0645\u064A\u0646 \u0627\u0644\u0648\u0633\u064A\u0637\u0629 fv." },
      pv: { name: "pv", detail: "\u0645\u0637\u0644\u0648\u0628. \u0627\u0644\u0642\u064A\u0645\u0629 \u0627\u0644\u062D\u0627\u0644\u064A\u0629\u060C \u0623\u0648 \u0627\u0644\u0645\u0628\u0644\u063A \u0627\u0644\u0625\u062C\u0645\u0627\u0644\u064A \u0627\u0644\u0630\u064A \u062A\u0633\u0627\u0648\u064A\u0647 \u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062F\u0641\u0639\u0627\u062A \u0627\u0644\u0645\u0633\u062A\u0642\u0628\u0644\u064A\u0629 \u0627\u0644\u0622\u0646." },
      fv: { name: "fv", detail: "\u0627\u0644\u0627\u062E\u062A\u064A\u0627\u0631\u064A. \u0627\u0644\u0642\u064A\u0645\u0629 \u0627\u0644\u0645\u0633\u062A\u0642\u0628\u0644\u064A\u0629 \u0623\u0648 \u0627\u0644\u0645\u064A\u0632\u0627\u0646\u064A\u0629 \u0627\u0644\u0646\u0642\u062F\u064A\u0629 \u0627\u0644\u062A\u064A \u062A\u0631\u064A\u062F \u062A\u062D\u0642\u064A\u0642\u0647\u0627 \u0628\u0639\u062F \u0625\u062A\u0645\u0627\u0645 \u0627\u0644\u062F\u0641\u0639\u0629 \u0627\u0644\u0623\u062E\u064A\u0631\u0629. \u0625\u0630\u0627 \u062A\u0645 \u062D\u0630\u0641 \u0627\u0644\u0648\u0633\u064A\u0637\u0629 fv\u060C \u0641\u0633\u064A\u0641\u062A\u0631\u0636 \u0623\u0646\u0647\u0627 0 (\u0627\u0644\u0642\u064A\u0645\u0629 \u0627\u0644\u0645\u0633\u062A\u0642\u0628\u0644\u064A\u0629 \u0644\u0642\u0631\u0636\u060C \u0645\u062B\u0644\u0627\u064B\u060C \u0647\u064A \u0635\u0641\u0631). \u0625\u0630\u0627 \u062A\u0645 \u062D\u0630\u0641 \u0627\u0644\u0648\u0633\u064A\u0637\u0629 fv\u060C \u0641\u064A\u062C\u0628 \u062A\u0636\u0645\u064A\u0646 \u0627\u0644\u0648\u0633\u064A\u0637\u0629 pmt." },
      type: { name: "type", detail: "\u0627\u0644\u0627\u062E\u062A\u064A\u0627\u0631\u064A. \u0627\u0644\u0631\u0642\u0645 0 \u0623\u0648 1 \u0648\u064A\u0634\u064A\u0631 \u0625\u0644\u0649 \u0645\u0648\u0639\u062F \u0627\u0633\u062A\u062D\u0642\u0627\u0642 \u0627\u0644\u062F\u0641\u0639\u0627\u062A." },
      guess: { name: "guess", detail: "\u0627\u0644\u0627\u062E\u062A\u064A\u0627\u0631\u064A. \u062A\u0642\u062F\u064A\u0631\u0643 \u0644\u0642\u064A\u0645\u0629 \u0627\u0644\u0645\u0639\u062F\u0644. \u0625\u0630\u0627 \u062A\u0645 \u062D\u0630\u0641 \u0627\u0644\u0648\u0633\u064A\u0637\u0629 guess\u060C \u0641\u0633\u064A\u064F\u0641\u062A\u0631\u0636 \u0623\u0646\u0647\u0627 10 \u0628\u0627\u0644\u0645\u0626\u0629. \u0625\u0630\u0627 \u0644\u0645 \u062A\u062A\u0642\u0627\u0631\u0628 \u0646\u062A\u0627\u0626\u062C \u0627\u0644\u062F\u0627\u0644\u0629 RATE\u060C \u0641\u062D\u0627\u0648\u0644 \u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0642\u064A\u0645 \u0645\u062E\u062A\u0644\u0641\u0629 \u0644\u0644\u0648\u0633\u064A\u0637\u0629 guess. \u062A\u062A\u0642\u0627\u0631\u0628 \u0646\u062A\u0627\u0626\u062C \u0627\u0644\u062F\u0627\u0644\u0629 RATE \u0639\u0627\u062F\u0629\u064B \u0625\u0630\u0627 \u0643\u0627\u0646\u062A \u0642\u064A\u0645\u0629 guess \u0628\u064A\u0646 0 \u06481." }
    }
