      pr: { name: "pr", detail: "\u0645\u0637\u0644\u0648\u0628. \u0633\u0639\u0631 \u0627\u0644\u0648\u0631\u0642\u0629 \u0627\u0644\u0645\u0627\u0644\u064A\u0629 \u0644\u0643\u0644 \u0642\u064A\u0645\u0629 \u0627\u0633\u0645\u064A\u0629 \u0642\u062F\u0631\u0647\u0627 100 \u0631.\u0633." },
