    functionParameter: {
      value: { name: "value", detail: "\u0645\u0637\u0644\u0648\u0628. \u0647\u064A \u0627\u0644\u0642\u064A\u0645\u0629 \u0627\u0644\u062A\u064A \u062A\u0631\u064A\u062F \u0627\u062E\u062A\u0628\u0627\u0631\u0647\u0627. \u064A\u0645\u0643\u0646 \u0644\u0648\u0633\u064A\u0637\u0629 \u0627\u0644\u0642\u064A\u0645\u0629 \u0623\u0646 \u062A\u0643\u0648\u0646 \u0639\u0628\u0627\u0631\u0629 \u0639\u0646 \u0642\u064A\u0645\u0629 \u0641\u0627\u0631\u063A\u0629 (\u062E\u0644\u064A\u0629 \u0641\u0627\u0631\u063A\u0629) \u0623\u0648 \u0642\u064A\u0645\u0629 \u062E\u0637\u0623 \u0623\u0648 \u0642\u064A\u0645\u0629 \u0645\u0646\u0637\u0642\u064A\u0629 \u0623\u0648 \u0646\u0635 \u0623\u0648 \u0631\u0642\u0645 \u0623\u0648 \u0642\u064A\u0645\u0629 \u0645\u0631\u062C\u0639\u064A\u0629 \u0623\u0648 \u0627\u0633\u0645 \u064A\u0634\u064A\u0631 \u0625\u0644\u0649 \u0623\u064A \u0645\u0646 \u0647\u0630\u0647." }
    }
