      array2: { name: "array2", detail: "\u0627\u0644\u0635\u0641\u064A\u0641 \u0627\u0644\u062B\u0627\u0646\u064A \u0627\u0644\u0645\u0631\u0627\u062F \u062A\u0639\u064A\u064A\u0646\u0647." },
      lambda: { name: "lambda", detail: "\u062F\u0627\u0644\u0629 LAMBDA \u064A\u062C\u0628 \u0623\u0646 \u062A\u0643\u0648\u0646 \u0627\u0644\u0648\u0633\u064A\u0637\u0629 \u0627\u0644\u0623\u062E\u064A\u0631\u0629\u060C \u0648\u0623\u0646 \u062A\u062A\u0636\u0645\u0646 \u0645\u0639\u0644\u0645\u0629 \u0644\u0643\u0644 \u0635\u0641\u064A\u0641 \u0645\u064F\u0645\u0631\u0651\u064E\u0631." }
