      rows: { name: "rows", detail: "\u0639\u062F\u062F \u0627\u0644\u0635\u0641\u0648\u0641 \u0627\u0644\u062A\u064A \u064A\u062C\u0628 \u0625\u0633\u0642\u0627\u0637\u0647\u0627. \u064A\u062A\u0645 \u0625\u0633\u0642\u0627\u0637 \u0642\u064A\u0645\u0629 \u0633\u0627\u0644\u0628\u0629 \u0645\u0646 \u0646\u0647\u0627\u064A\u0629 \u0627\u0644\u0635\u0641\u064A\u0641." },
