      ifEmpty: { name: "if_empty", detail: "\u0627\u0644\u0642\u064A\u0645\u0629 \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0625\u0631\u062C\u0627\u0639\u0647\u0627 \u0625\u0630\u0627 \u0643\u0627\u0646\u062A \u0643\u0644 \u0627\u0644\u0642\u064A\u0645 \u0641\u064A \u0627\u0644\u0635\u0641\u064A\u0641 \u0627\u0644\u0645\u0636\u0645\u0646 \u0641\u0627\u0631\u063A\u0629 (\u0644\u0627 \u064A\u0642\u0648\u0645 \u0639\u0627\u0645\u0644 \u0627\u0644\u062A\u0635\u0641\u064A\u0629 \u0628\u0625\u0631\u062C\u0627\u0639 \u0623\u064A \u0634\u064A\u0621)" }
