    abstract: "\u0625\u0644\u062D\u0627\u0642 \u0627\u0644\u0635\u0641\u0627\u0626\u0641 \u0623\u0641\u0642\u064A\u0627\u064B \u0648\u0628\u062A\u0633\u0644\u0633\u0644 \u0644\u0625\u0631\u062C\u0627\u0639 \u0635\u0641\u064A\u0641 \u0623\u0643\u0628\u0631.",
