      altText: { name: "alt_text", detail: "\u0646\u0635 \u0628\u062F\u064A\u0644 \u064A\u0635\u0641 \u0627\u0644\u0635\u0648\u0631\u0629 \u0644\u0623\u063A\u0631\u0627\u0636 \u0625\u0645\u0643\u0627\u0646\u064A\u0629 \u0627\u0644\u0648\u0635\u0648\u0644." },
