      height: { name: "height", detail: "\u0627\u0644\u0627\u0631\u062A\u0641\u0627\u0639 \u0627\u0644\u0645\u062E\u0635\u0635 \u0644\u0644\u0635\u0648\u0631\u0629 \u0628\u0627\u0644\u0628\u0643\u0633\u0644." },
      width: { name: "width", detail: "\u0627\u0644\u0639\u0631\u0636 \u0627\u0644\u0645\u062E\u0635\u0635 \u0644\u0644\u0635\u0648\u0631\u0629 \u0628\u0627\u0644\u0628\u0643\u0633\u0644." }
