      wrapCount: { name: "wrap_count", detail: "\u0627\u0644\u062D\u062F \u0627\u0644\u0623\u0642\u0635\u0649 \u0644\u0639\u062F\u062F \u0627\u0644\u0642\u064A\u0645 \u0644\u0643\u0644 \u0639\u0645\u0648\u062F." },
