      padWith: { name: "pad_with", detail: "\u0627\u0644\u0642\u064A\u0645\u0629 \u0627\u0644\u062A\u064A \u0633\u064A\u062A\u0645 \u0644\u0648\u062D\u0629 \u0628\u0647\u0627. \u0627\u0644\u0625\u0639\u062F\u0627\u062F \u0627\u0644\u0627\u0641\u062A\u0631\u0627\u0636\u064A \u0647\u0648 #N/A." }
