    abstract: "\u062A\u064F\u0631\u062C\u0639 \u0647\u0630\u0647 \u0627\u0644\u062F\u0627\u0644\u0629 \u0627\u0644\u0642\u064A\u0645\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064A\u0629 \u0644\u0642\u0648\u0633 \u0638\u0644 \u062A\u0645\u0627\u0645 \u0627\u0644\u0632\u0627\u0648\u064A\u0629 \u0623\u0648 \u0638\u0644 \u0627\u0644\u062A\u0645\u0627\u0645 \u0627\u0644\u0639\u0643\u0633\u064A \u0644\u0631\u0642\u0645.",
