    description: "\u062A\u064F\u0631\u062C\u0639 \u0647\u0630\u0647 \u0627\u0644\u0627\u0644\u0629 \u0627\u0644\u0645\u062A\u0648\u0633\u0637 (\u0627\u0644\u0648\u0633\u0637 \u0627\u0644\u062D\u0633\u0627\u0628\u064A) \u0644\u0643\u0627\u0641\u0629 \u0627\u0644\u062E\u0644\u0627\u064A\u0627 \u0627\u0644\u062A\u064A \u062A\u0637\u0627\u0628\u0642 \u0645\u0639\u0627\u064A\u064A\u0631 \u0645\u062A\u0639\u062F\u062F\u0629.",
    abstract: "\u062A\u064F\u0631\u062C\u0639 \u0647\u0630\u0647 \u0627\u0644\u0627\u0644\u0629 \u0627\u0644\u0645\u062A\u0648\u0633\u0637 (\u0627\u0644\u0648\u0633\u0637 \u0627\u0644\u062D\u0633\u0627\u0628\u064A) \u0644\u0643\u0627\u0641\u0629 \u0627\u0644\u062E\u0644\u0627\u064A\u0627 \u0627\u0644\u062A\u064A \u062A\u0637\u0627\u0628\u0642 \u0645\u0639\u0627\u064A\u064A\u0631 \u0645\u062A\u0639\u062F\u062F\u0629.",
    links: [
      {
        title: "\u0627\u0644\u062A\u0639\u0644\u064A\u0645\u0627\u062A",
        url: "https://support.microsoft.com/ar-sa/excel/functions/averageifs-function"
      }
    ],
    functionParameter: {
      averageRange: { name: "average_range", detail: "\u0645\u0637\u0644\u0648\u0628. \u0647\u064A \u0648\u0627\u062D\u062F\u0629 \u0623\u0648 \u0623\u0643\u062B\u0631 \u0645\u0646 \u0627\u0644\u062E\u0644\u0627\u064A\u0627 \u0627\u0644\u0645\u0631\u0627\u062F \u062D\u0633\u0627\u0628 \u0627\u0644\u0645\u062A\u0648\u0633\u0637 \u0644\u0647\u0627\u060C \u0628\u0645\u0627 \u0641\u064A \u0630\u0644\u0643 \u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0623\u0648 \u0627\u0644\u0623\u0633\u0645\u0627\u0621 \u0623\u0648 \u0627\u0644\u0635\u0641\u0627\u0626\u0641 \u0623\u0648 \u0627\u0644\u0645\u0631\u0627\u062C\u0639 \u0627\u0644\u062A\u064A \u062A\u062D\u062A\u0648\u064A \u0639\u0644\u0649 \u0623\u0631\u0642\u0627\u0645." },
      criteriaRange1: { name: "criteria_range1", detail: "\u0625\u0646 \u0627\u0644\u0648\u0633\u064A\u0637\u0629 Criteria_range1 \u0645\u0637\u0644\u0648\u0628\u0629\u060C \u0623\u0645\u0627 \u0648\u0633\u0627\u0626\u0637 criteria_range \u0627\u0644\u062A\u0627\u0644\u064A\u0629 \u0641\u0647\u064A \u0627\u062E\u062A\u064A\u0627\u0631\u064A\u0629. \u0627\u0644\u0646\u0637\u0627\u0642\u0627\u062A \u0645\u0646 1 \u0625\u0644\u0649 127 \u0627\u0644\u062A\u064A \u064A\u062A\u0645 \u0641\u064A\u0647\u0627 \u062A\u0642\u064A\u064A\u0645 \u0627\u0644\u0645\u0639\u0627\u064A\u064A\u0631 \u0627\u0644\u0645\u0642\u062A\u0631\u0646\u0629 \u0628\u0647\u0627." },
      criteria1: { name: "criteria1", detail: 'Criteria1 \u0645\u0637\u0644\u0648\u0628\u060C \u0627\u0644\u0645\u0639\u0627\u064A\u064A\u0631 \u0627\u0644\u0644\u0627\u062D\u0642\u0629 \u0627\u062E\u062A\u064A\u0627\u0631\u064A\u0629. \u0627\u0644\u0645\u0639\u0627\u064A\u064A\u0631 \u0645\u0646 1 \u0625\u0644\u0649 127 \u0639\u0644\u0649 \u0634\u0643\u0644 \u0631\u0642\u0645 \u0623\u0648 \u062A\u0639\u0628\u064A\u0631 \u0623\u0648 \u0645\u0631\u062C\u0639 \u062E\u0644\u064A\u0629 \u0623\u0648 \u0646\u0635 \u0644\u062A\u0639\u0631\u064A\u0641 \u0627\u0644\u062E\u0644\u0627\u064A\u0627 \u0627\u0644\u062A\u064A \u0633\u064A\u062A\u0645 \u062D\u0633\u0627\u0628 \u0627\u0644\u0645\u062A\u0648\u0633\u0637 \u0644\u0647\u0627. \u0639\u0644\u0649 \u0633\u0628\u064A\u0644 \u0627\u0644\u0645\u062B\u0627\u0644\u060C \u064A\u0645\u0643\u0646 \u0627\u0644\u062A\u0639\u0628\u064A\u0631 \u0639\u0646 \u0627\u0644\u0645\u0639\u0627\u064A\u064A\u0631 \u0639\u0644\u0649 \u0623\u0646\u0647\u0627 32 \u0623\u0648 "32" \u0623\u0648 ">32" \u0623\u0648 "\u062A\u0641\u0627\u062D" \u0623\u0648 B4.' },
      criteriaRange2: { name: "criteria_range2", detail: "\u0625\u0646 \u0627\u0644\u0648\u0633\u064A\u0637\u0629 Criteria_range1 \u0645\u0637\u0644\u0648\u0628\u0629\u060C \u0623\u0645\u0627 \u0648\u0633\u0627\u0626\u0637 criteria_range \u0627\u0644\u062A\u0627\u0644\u064A\u0629 \u0641\u0647\u064A \u0627\u062E\u062A\u064A\u0627\u0631\u064A\u0629. \u0627\u0644\u0646\u0637\u0627\u0642\u0627\u062A \u0645\u0646 1 \u0625\u0644\u0649 127 \u0627\u0644\u062A\u064A \u064A\u062A\u0645 \u0641\u064A\u0647\u0627 \u062A\u0642\u064A\u064A\u0645 \u0627\u0644\u0645\u0639\u0627\u064A\u064A\u0631 \u0627\u0644\u0645\u0642\u062A\u0631\u0646\u0629 \u0628\u0647\u0627." },
      criteria2: { name: "criteria2", detail: 'Criteria1 \u0645\u0637\u0644\u0648\u0628\u060C \u0627\u0644\u0645\u0639\u0627\u064A\u064A\u0631 \u0627\u0644\u0644\u0627\u062D\u0642\u0629 \u0627\u062E\u062A\u064A\u0627\u0631\u064A\u0629. \u0627\u0644\u0645\u0639\u0627\u064A\u064A\u0631 \u0645\u0646 1 \u0625\u0644\u0649 127 \u0639\u0644\u0649 \u0634\u0643\u0644 \u0631\u0642\u0645 \u0623\u0648 \u062A\u0639\u0628\u064A\u0631 \u0623\u0648 \u0645\u0631\u062C\u0639 \u062E\u0644\u064A\u0629 \u0623\u0648 \u0646\u0635 \u0644\u062A\u0639\u0631\u064A\u0641 \u0627\u0644\u062E\u0644\u0627\u064A\u0627 \u0627\u0644\u062A\u064A \u0633\u064A\u062A\u0645 \u062D\u0633\u0627\u0628 \u0627\u0644\u0645\u062A\u0648\u0633\u0637 \u0644\u0647\u0627. \u0639\u0644\u0649 \u0633\u0628\u064A\u0644 \u0627\u0644\u0645\u062B\u0627\u0644\u060C \u064A\u0645\u0643\u0646 \u0627\u0644\u062A\u0639\u0628\u064A\u0631 \u0639\u0646 \u0627\u0644\u0645\u0639\u0627\u064A\u064A\u0631 \u0639\u0644\u0649 \u0623\u0646\u0647\u0627 32 \u0623\u0648 "32" \u0623\u0648 ">32" \u0623\u0648 "\u062A\u0641\u0627\u062D" \u0623\u0648 B4.' }
    }
