      probabilityS: { name: "probability_s", detail: "\u0645\u0637\u0644\u0648\u0628. \u0648\u0647\u064A \u0627\u062D\u062A\u0645\u0627\u0644 \u0627\u0644\u0646\u062C\u0627\u062D \u0641\u064A \u0643\u0644 \u062A\u062C\u0631\u0628\u0629." },
      cumulative: { name: "cumulative", detail: "\u0645\u0637\u0644\u0648\u0628. \u0648\u0647\u064A \u0627\u0644\u0642\u064A\u0645\u0629 \u0627\u0644\u0645\u0646\u0637\u0642\u064A\u0629 \u0627\u0644\u062A\u064A \u062A\u062D\u062F\u062F \u0634\u0643\u0644 \u0627\u0644\u062F\u0627\u0644\u0629. \u0625\u0630\u0627 \u0643\u0627\u0646\u062A \u0642\u064A\u0645\u0629 cumulative \u062A\u0633\u0627\u0648\u064A TRUE\u060C \u0641\u0625\u0646 BINOM.DIST \u062A\u064F\u0631\u062C\u0639 \u062F\u0627\u0644\u0629 \u0627\u0644\u062A\u0648\u0632\u064A\u0639 \u0627\u0644\u062A\u0631\u0627\u0643\u0645\u064A\u060C \u0648\u0647\u064A \u0627\u0644\u0627\u062D\u062A\u0645\u0627\u0644 \u0628\u0648\u062C\u0648\u062F number_s \u0644\u0639\u062F\u062F \u0645\u0631\u0627\u062A \u0627\u0644\u0646\u062C\u0627\u062D \u0639\u0644\u0649 \u0627\u0644\u0623\u0643\u062B\u0631\u060C \u0648\u0625\u0630\u0627 \u0643\u0627\u0646\u062A \u062A\u0633\u0627\u0648\u064A FALSE\u060C \u0641\u0625\u0646\u0647\u0627 \u062A\u064F\u0631\u062C\u0639 \u062F\u0627\u0644\u0629 \u0627\u0644\u0627\u062D\u062A\u0645\u0627\u0644\u0627\u062A \u063A\u064A\u0631 \u0627\u0644\u062A\u0631\u0627\u0643\u0645\u064A\u0629\u060C \u0648\u0647\u064A \u0627\u0644\u0627\u062D\u062A\u0645\u0627\u0644 \u0628\u0648\u062C\u0648\u062F number_s \u0644\u0639\u062F\u062F \u0645\u0631\u0627\u062A \u0627\u0644\u0646\u062C\u0627\u062D \u0628\u0627\u0644\u0636\u0628\u0637." }
