    functionParameter: {
      alpha: { name: "alpha", detail: "\u0645\u0637\u0644\u0648\u0628. \u0645\u0633\u062A\u0648\u0649 \u0627\u0644\u062F\u0644\u0627\u0644\u0629 \u0627\u0644\u0645\u064F\u0633\u062A\u062E\u062F\u0645 \u0644\u062D\u0633\u0627\u0628 \u0645\u0633\u062A\u0648\u0649 \u0627\u0644\u062B\u0642\u0629. \u064A\u0633\u0627\u0648\u064A \u0645\u0633\u062A\u0648\u0649 \u0627\u0644\u062B\u0642\u0629 \u200E100*(1 - alpha)%\u200E\u060C \u0623\u0648 \u0628\u0639\u0628\u0627\u0631\u0629 \u0623\u062E\u0631\u0649\u060C \u062A\u0634\u064A\u0631 alpha \u0630\u0627\u062A \u0627\u0644\u0642\u064A\u0645\u0629 0,05 \u0625\u0644\u0649 \u0645\u0633\u062A\u0648\u0649 \u062B\u0642\u0629 \u0628\u0646\u0633\u0628\u0629 95 \u0641\u064A \u0627\u0644\u0645\u0626\u0629." },
      standardDev: { name: "standard_dev", detail: "\u0645\u0637\u0644\u0648\u0628. \u0627\u0644\u0627\u0646\u062D\u0631\u0627\u0641 \u0627\u0644\u0645\u0639\u064A\u0627\u0631\u064A \u0644\u0644\u0645\u062D\u062A\u0648\u0649 \u0627\u0644\u062E\u0627\u0635 \u0628\u0646\u0637\u0627\u0642 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0648\u0627\u0644\u0630\u064A \u0645\u0646 \u0627\u0644\u0645\u0641\u062A\u0631\u0636 \u0623\u0646 \u064A\u0643\u0648\u0646 \u0645\u0639\u0631\u0648\u0641\u0627\u064B." },
      size: { name: "size", detail: "\u0645\u0637\u0644\u0648\u0628. \u062D\u062C\u0645 \u0627\u0644\u0639\u064A\u0646\u0629." }
    }
