      criteria1: { name: "criteria1", detail: "\u0647\u064A \u0645\u0639\u0627\u064A\u064A\u0631 \u0628\u0635\u064A\u063A\u0629 \u0623\u0631\u0642\u0627\u0645 \u0623\u0648 \u062A\u0639\u0628\u064A\u0631\u0627\u062A \u0623\u0648 \u0646\u0635\u0648\u0635 \u062A\u062D\u062F\u062F \u0627\u0644\u062E\u0644\u0627\u064A\u0627 \u0627\u0644\u062A\u064A \u0633\u064A\u062A\u0645 \u062A\u0642\u064A\u064A\u0645\u0647\u0627 \u0643\u062D\u062F \u0623\u0642\u0635\u0649. \u062A\u0639\u0645\u0644 \u0645\u062C\u0645\u0648\u0639\u0629 \u0627\u0644\u0645\u0639\u0627\u064A\u064A\u0631 \u0646\u0641\u0633\u0647\u0627 \u0645\u0639 \u0627\u0644\u062F\u0627\u0644\u0627\u062A MINIFS \u0648 SUMIFS \u0648 AVERAGEIFS ." },
      criteriaRange2: { name: "criteriaRange2", detail: "\u0647\u064A \u0627\u0644\u0646\u0637\u0627\u0642\u0627\u062A \u0627\u0644\u0625\u0636\u0627\u0641\u064A\u0629 \u0648\u0627\u0644\u0645\u0639\u0627\u064A\u064A\u0631 \u0627\u0644\u0645\u0642\u062A\u0631\u0646\u0629 \u0628\u0647\u0627. \u064A\u0645\u0643\u0646\u0643 \u0625\u062F\u062E\u0627\u0644 \u0645\u0627 \u064A\u0635\u0644 \u0625\u0644\u0649 126 \u0632\u0648\u062C\u0627\u064B \u0645\u0646 \u0627\u0644\u0646\u0637\u0627\u0642\u0627\u062A/\u0627\u0644\u0645\u0639\u0627\u064A\u064A\u0631." },
      criteria2: { name: "criteria2", detail: "\u0647\u064A \u0627\u0644\u0646\u0637\u0627\u0642\u0627\u062A \u0627\u0644\u0625\u0636\u0627\u0641\u064A\u0629 \u0648\u0627\u0644\u0645\u0639\u0627\u064A\u064A\u0631 \u0627\u0644\u0645\u0642\u062A\u0631\u0646\u0629 \u0628\u0647\u0627. \u064A\u0645\u0643\u0646\u0643 \u0625\u062F\u062E\u0627\u0644 \u0645\u0627 \u064A\u0635\u0644 \u0625\u0644\u0649 126 \u0632\u0648\u062C\u0627\u064B \u0645\u0646 \u0627\u0644\u0646\u0637\u0627\u0642\u0627\u062A/\u0627\u0644\u0645\u0639\u0627\u064A\u064A\u0631." }
