    functionParameter: {
      value1: { name: "value1", detail: "\u0627\u0644\u0631\u0642\u0645 \u0627\u0644\u0623\u0648\u0644 \u0623\u0648 \u0645\u0631\u062C\u0639 \u0627\u0644\u062E\u0644\u064A\u0629 \u0623\u0648 \u0627\u0644\u0646\u0637\u0627\u0642 \u0627\u0644\u0630\u064A \u062A\u0631\u064A\u062F \u062D\u0633\u0627\u0628 \u0627\u0644\u0642\u064A\u0645\u0629 \u0627\u0644\u0635\u063A\u0631\u0649 \u0645\u0646\u0647." },
      value2: { name: "value2", detail: "\u0623\u0631\u0642\u0627\u0645 \u0623\u0648 \u0645\u0631\u0627\u062C\u0639 \u062E\u0644\u0627\u064A\u0627 \u0623\u0648 \u0646\u0637\u0627\u0642\u0627\u062A \u0625\u0636\u0627\u0641\u064A\u0629 \u0644\u062D\u0633\u0627\u0628 \u0627\u0644\u0642\u064A\u0645\u0629 \u0627\u0644\u0635\u063A\u0631\u0649 \u0645\u0646\u0647\u0627\u060C \u0628\u062D\u062F \u0623\u0642\u0635\u0649 255." }
    }
