      cumulative: { name: "cumulative", detail: "\u0645\u0637\u0644\u0648\u0628. \u062A\u062D\u062F\u062F \u0647\u0630\u0647 \u0627\u0644\u0648\u0633\u064A\u0637\u0629 \u0634\u0643\u0644 \u0627\u0644\u062F\u0627\u0644\u0629." }
