    "\u{1F9D1}\u{1F3FF}\u200D\u{1F91D}\u200D\u{1F9D1}\u{1F3FB}": "\u0623\u0634\u062E\u0627\u0635 \u064A\u0645\u0633\u0643\u0648\u0646 \u0628\u0623\u064A\u062F\u064A \u0628\u0639\u0636\u0647\u0645: \u0628\u0634\u0631\u0629 \u0628\u0644\u0648\u0646 \u063A\u0627\u0645\u0642 \u0648\u0628\u0634\u0631\u0629 \u0628\u0644\u0648\u0646 \u0641\u0627\u062A\u062D",
    "\u{1F9D1}\u{1F3FF}\u200D\u{1F91D}\u200D\u{1F9D1}\u{1F3FC}": "\u0623\u0634\u062E\u0627\u0635 \u064A\u0645\u0633\u0643\u0648\u0646 \u0628\u0623\u064A\u062F\u064A \u0628\u0639\u0636\u0647\u0645: \u0628\u0634\u0631\u0629 \u0628\u0644\u0648\u0646 \u063A\u0627\u0645\u0642 \u0648\u0628\u0634\u0631\u0629 \u0628\u0644\u0648\u0646 \u0641\u0627\u062A\u062D \u0648\u0645\u0639\u062A\u062F\u0644",
    "\u{1F9D1}\u{1F3FF}\u200D\u{1F91D}\u200D\u{1F9D1}\u{1F3FD}": "\u0623\u0634\u062E\u0627\u0635 \u064A\u0645\u0633\u0643\u0648\u0646 \u0628\u0623\u064A\u062F\u064A \u0628\u0639\u0636\u0647\u0645: \u0628\u0634\u0631\u0629 \u0628\u0644\u0648\u0646 \u063A\u0627\u0645\u0642 \u0648\u0628\u0634\u0631\u0629 \u0628\u0644\u0648\u0646 \u0645\u0639\u062A\u062F\u0644",
    "\u{1F9D1}\u{1F3FF}\u200D\u{1F91D}\u200D\u{1F9D1}\u{1F3FE}": "\u0623\u0634\u062E\u0627\u0635 \u064A\u0645\u0633\u0643\u0648\u0646 \u0628\u0623\u064A\u062F\u064A \u0628\u0639\u0636\u0647\u0645: \u0628\u0634\u0631\u0629 \u0628\u0644\u0648\u0646 \u063A\u0627\u0645\u0642 \u0648\u0628\u0634\u0631\u0629 \u0628\u0644\u0648\u0646 \u0645\u0639\u062A\u062F\u0644 \u0645\u0627\u0626\u0644 \u0644\u0644\u063A\u0627\u0645\u0642",
    "\u{1F9D1}\u{1F3FF}\u200D\u{1F91D}\u200D\u{1F9D1}\u{1F3FF}": "\u0623\u0634\u062E\u0627\u0635 \u064A\u0645\u0633\u0643\u0648\u0646 \u0628\u0623\u064A\u062F\u064A \u0628\u0639\u0636\u0647\u0645: \u0628\u0634\u0631\u0629 \u0628\u0644\u0648\u0646 \u063A\u0627\u0645\u0642",
    "\u{1F46D}": "\u0627\u0645\u0631\u0623\u062A\u0627\u0646 \u062A\u0645\u0633\u0643\u0627\u0646 \u0628\u064A\u062F \u0628\u0639\u0636\u0647\u0645\u0627",
    "\u{1F46D}\u{1F3FB}": "\u0627\u0645\u0631\u0623\u062A\u0627\u0646 \u062A\u0645\u0633\u0643\u0627\u0646 \u0628\u064A\u062F \u0628\u0639\u0636\u0647\u0645\u0627: \u0628\u0634\u0631\u0629 \u0628\u0644\u0648\u0646 \u0641\u0627\u062A\u062D",
